import{_ as e,c as a,o as t,a2 as o}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"Error pages","description":"","frontmatter":{"sidebarPos":8,"sidebarTitle":"Error pages","sidebarGroupTitle":"Cms","outline":"deep"},"headers":[],"relativePath":"guide/cms/error-pages.md","filePath":"guide/cms/error-pages.md","lastUpdated":1785337581000}'),r={name:"guide/cms/error-pages.md"},d=o(`<h1 id="error-pages" tabindex="-1">Error pages <a class="header-anchor" href="#error-pages" aria-label="Permalink to &quot;Error pages&quot;">​</a></h1><p>The <strong>ErrorPage</strong> module manages HTTP <strong>403 / 404 / 500</strong> responses. CMS records are optional: package <strong>builtin Blade views</strong> under <code>error_page::error_page.{code}</code> are full documents that <code>@extends(&#39;error_page::error_page.standalone&#39;)</code> with Vuetify content. When a host theme body override exists and a LayoutBuilder shell is bound, that override is injected into the marketing shell instead.</p><p>Unlike CMR content, error pages have <strong>no public URL</strong>, no ParentSegment, and no slug — they are never resolved through the CMS catch-all.</p><p>Runtime rendering is handled by <code>Modules\\ErrorPage\\Support\\ErrorPageRenderer</code>, registered from <code>ErrorPageServiceProvider</code> for <code>HttpExceptionInterface</code> status codes <code>403</code>, <code>404</code>, and <code>500</code>. Panel requests (<code>Modularous::isPanelUrl</code>) are excluded so the admin panel keeps Laravel’s default error handling.</p><h2 id="feature-flags" tabindex="-1">Feature flags <a class="header-anchor" href="#feature-flags" aria-label="Permalink to &quot;Feature flags&quot;">​</a></h2><table><thead><tr><th>Config / env</th><th>Default</th></tr></thead><tbody><tr><td><code>modularous.cms_features.error_pages_enabled</code> / <code>MODULAROUS_CMS_ERROR_PAGES_ENABLED</code></td><td><code>true</code></td></tr><tr><td><code>modularous.cms_features.error_pages_cache_enabled</code> / <code>MODULAROUS_CMS_ERROR_PAGES_CACHE_ENABLED</code></td><td><code>true</code></td></tr></tbody></table><p>When <strong>error_pages_enabled</strong> is off, the renderer returns <code>null</code> and the exception <code>renderable</code> skips ErrorPage → <strong>Laravel’s default</strong> error page.</p><p>When <strong>error_pages_cache_enabled</strong> is off (or <code>presentationItem.store=none</code> / module <code>presentationItem</code> type off), published ErrorPage HTML is rendered on every request. Cache is model-scoped (<code>ErrorPagePresentationCache</code> / <code>StaleFileCache</code>) and cleared on ErrorPage save/delete. Admin purge/warm use that same store — warm delegates via <code>ErrorPagePresentationCache::warm()</code> (ErrorPage has no UrlRoute, so the generic CMS path warm is skipped).</p><h2 id="resolution-strategy" tabindex="-1">Resolution strategy <a class="header-anchor" href="#resolution-strategy" aria-label="Permalink to &quot;Resolution strategy&quot;">​</a></h2><ol><li>Feature flag off → Laravel.</li><li>Lookup <code>ErrorPage</code> by <code>error_code</code> (skipped if the table is missing → treat as no row).</li><li><strong>Found + unpublished</strong> → Laravel (CMS intentionally disabled for that code).</li><li><strong>Found + published</strong> → CMS path: host/package body override inside LayoutBuilder when both exist; otherwise package builtin full document.</li><li><strong>Not found</strong> → builtin fallback: theme body override (plain document) or Vuetify builtin full page (<code>@extends</code> standalone + ModularousVite).</li></ol><table><thead><tr><th>Condition</th><th>Result</th></tr></thead><tbody><tr><td>Flag off</td><td>Laravel</td></tr><tr><td>Unpublished row</td><td>Laravel</td></tr><tr><td>Published row + override + LayoutBuilder</td><td>LayoutBuilder shell + body fragment</td></tr><tr><td>Published row, no usable override</td><td>Builtin full document</td></tr><tr><td>No row / table missing</td><td>Builtin (+ optional app override)</td></tr></tbody></table><p>Unpublished ≠ missing: unpublishing opts out; absence still uses builtin fallbacks.</p><h3 id="traits" tabindex="-1">Traits <a class="header-anchor" href="#traits" aria-label="Permalink to &quot;Traits&quot;">​</a></h3><table><thead><tr><th>Entity</th><th>Repository</th></tr></thead><tbody><tr><td><code>HasPageLayout</code> + <code>Publishable</code> + <code>HasScopes</code></td><td><code>PageLayoutTrait</code> + <code>PublishableTrait</code></td></tr></tbody></table><p>Do <strong>not</strong> use <code>IsCmr</code> / <code>HasParentSegment</code> — error pages are not front URL routes.</p><h2 id="why-seed-at-all" tabindex="-1">Why seed at all? <a class="header-anchor" href="#why-seed-at-all" aria-label="Permalink to &quot;Why seed at all?&quot;">​</a></h2><p>Seeding is <strong>optional</strong> for seeing a non-Laravel error page. Use <code>modularous:create:error-page-defaults</code> when you want:</p><ul><li>Admin-managed published/unpublished toggles per code</li><li>A <code>PageLayout</code> binding so a <strong>host body override</strong> sits inside a LayoutBuilder shell (head / body / footer)</li></ul><p>Without seeding, visitors still get the Vuetify module builtin (or your app body override) as a standalone HTML document.</p><h2 id="activation-command" tabindex="-1">Activation &amp; command <a class="header-anchor" href="#activation-command" aria-label="Permalink to &quot;Activation &amp; command&quot;">​</a></h2><ol><li>Enable the module (<code>modules_statuses.json</code> → <code>&quot;ErrorPage&quot;: true</code>).</li><li>Ensure <code>cms_features.error_pages_enabled</code> is true (default).</li><li>Migrate if you want CMS rows: <code>php artisan modularous:migrate ErrorPage</code>.</li><li>Optionally seed defaults:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:create:error-page-defaults</span></span></code></pre></div><p>Optional flags:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Bind PageLayout to a specific LayoutBuilder slug</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:create:error-page-defaults</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --layout-slug=your-theme</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Re-publish / update existing ErrorPage rows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:create:error-page-defaults</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p>LayoutBuilder resolution (first match wins): <code>--layout-slug</code> → <code>cms_layout_builder.default_layout_slug</code> → <code>CmsPageLayoutResolver::defaultLayoutBuilder()</code> (includes <code>cms_page_layouts.default_layout_builder_id</code>). The package does <strong>not</strong> default to a host-specific theme slug.</p><p>If no LayoutBuilder is resolved, the command still creates/updates <code>ErrorPage</code> rows and warns that <code>PageLayout</code> will be stored without <code>layout_builder_id</code> (standalone shell until a builder is linked).</p><h2 id="body-priority-highest-first" tabindex="-1">Body priority (highest first) <a class="header-anchor" href="#body-priority-highest-first" aria-label="Permalink to &quot;Body priority (highest first)&quot;">​</a></h2><p>Given status <code>404</code> and a resolved LayoutBuilder slug (from PageLayout / config / default builder):</p><table><thead><tr><th>Priority</th><th>View name</th><th>Role</th></tr></thead><tbody><tr><td>1</td><td><code>cms.layout_builder.{slug}.404</code></td><td>App theme <strong>body override</strong> — disk: <code>resources/views/cms/layout_builder/{slug}/404.blade.php</code>. <strong>Body fragment only</strong>.</td></tr><tr><td>2</td><td><code>cms::layout_builder.{slug}.404</code></td><td>Package Cms namespace fallback for the same segment/code</td></tr></tbody></table><p>Package builtin UI (no usable override): <code>error_page::error_page.404</code> which <code>@extends(&#39;error_page::error_page.standalone&#39;)</code> with:</p><div class="language-blade vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">blade</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ModularousVite::useHotFile(public_path(&#39;modularous.hot&#39;))-&gt;withEntryPoints([&#39;src/js/core-free.js&#39;])</span></span></code></pre></div><p>(<code>core-free.js</code> mounts Vue/Vuetify on <code>#admin</code>, same pattern as other free Modularous layouts; not Inertia.)</p><p>Gates before body resolution: feature flag off or unpublished row → Laravel (no body render). Candidate list for shell fragments: <code>ErrorPageRenderer::bodyViewCandidates()</code> (overrides only).</p><p>App overrides apply for <strong>both</strong> published CMS and no-record builtin paths.</p><h3 id="host-app-example" tabindex="-1">Host app example <a class="header-anchor" href="#host-app-example" aria-label="Permalink to &quot;Host app example&quot;">​</a></h3><p>Marketing / theme 404 body override (host app, not the package):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>resources/views/cms/layout_builder/{your-layout-slug}/404.blade.php</span></span></code></pre></div><p>Set <code>MODULAROUS_CMS_LAYOUT_DEFAULT_SLUG</code> (or seed PageLayout with that builder). Without seeding, unknown URLs render that override via the plain document (or the Vuetify builtin via standalone). After seeding + PageLayout + override, the same body sits inside the LayoutBuilder shell.</p><h2 id="view-namespaces" tabindex="-1">View namespaces <a class="header-anchor" href="#view-namespaces" aria-label="Permalink to &quot;View namespaces&quot;">​</a></h2><table><thead><tr><th>Namespace / pattern</th><th>Meaning</th><th>Typical path</th></tr></thead><tbody><tr><td><code>error_page::…</code></td><td>ErrorPage module views (snake of <code>ErrorPage</code>)</td><td>Package: <code>modules/ErrorPage/Resources/views/…</code> → e.g. <code>error_page::error_page.404</code>, <code>error_page::error_page.standalone</code>, <code>error_page::error_page.plain</code></td></tr><tr><td><code>cms.layout_builder.{slug}.{segmentOrCode}</code></td><td>Host app LayoutBuilder theme (no <code>::</code>)</td><td><code>resources/views/cms/layout_builder/{slug}/{segmentOrCode}.blade.php</code></td></tr><tr><td><code>cms::layout_builder.{slug}.{segmentOrCode}</code></td><td>Cms module / package fallback</td><td>Cms module views under <code>layout_builder/{slug}/</code></td></tr></tbody></table><p>Convention matches other CMS themes: see <a href="./layout-builders">Layout builders</a> for shell segments (<code>head</code> / <code>body</code> / <code>footer</code>); error codes reuse the same <code>{slug}</code> folder for body overrides (<code>404</code>, <code>403</code>, <code>500</code>).</p><p>After editing views: <code>php artisan view:clear</code>.</p><h2 id="panel" tabindex="-1">Panel <a class="header-anchor" href="#panel" aria-label="Permalink to &quot;Panel&quot;">​</a></h2><p>Admin route config: <code>error-pages</code> with Selectable <code>error_code</code> (<code>403</code> / <code>404</code> / <code>500</code>, unique) and a <code>published</code> switch.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./overview">CMS Overview</a> — public presentation stack</li><li><a href="./page-layouts">Page layouts</a> — <code>HasPageLayout</code> binding used by ErrorPage</li><li><a href="./layout-builders">Layout builders</a> — document shell around the error body</li></ul>`,46),s=[d];function i(l,n,c,u,h,p){return t(),a("div",null,s)}const m=e(r,[["render",i]]);export{b as __pageData,m as default};
